// REST: Synchronous call using WebClient
public Mono<UserDto> getUser(String id) {
    return webClient.get().uri("/users/{id}", id).retrieve().bodyToMono(UserDto.class);
}

// Messaging: Asynchronous event emission using Spring Cloud Stream
public void publishOrder(OrderEvent event) {
    streamBridge.send("order-out-0", event);
}
